6	/**
7	 * @description Disconnect service from dependent containers.
8	 * @example
9	 * disconnect();
10	 */
11	async function disconnect() {
12	  let container;
13	
14	  // Stop backup reccurent job
15	  if (this.backupScheduledJob) {
16	    this.backupScheduledJob.cancel();
17	  }
18	
19	  // Disconnect from MQTT broker
20	  if (this.mqttClient) {
21	    logger.debug(`Disconnecting existing MQTT server...`);
22	    this.mqttClient.end();
23	    this.mqttClient.removeAllListeners();
24	    this.mqttClient = null;
25	  } else {
26	    logger.debug('Not connected');
27	  }
28	  this.gladysConnected = false;
29	  this.emitStatusEvent();
30	
31	  // Stop & remove MQTT container
32	  let dockerContainer = await this.gladys.system.getContainers({
33	    all: true,
34	    filters: { name: [mqttContainerDescriptor.name] },
35	  });
36	  if (dockerContainer.length > 0) {
37	    [container] = dockerContainer;
38	    await this.gladys.system.stopContainer(container.id);
39	    await this.gladys.system.removeContainer(container.id);
40	  }
41	  this.mqttRunning = false;
42	  this.emitStatusEvent();
43	
44	  // Stop & remove zigbee2mqtt container
45	  dockerContainer = await this.gladys.system.getContainers({
46	    all: true,
47	    filters: { name: [zigbee2mqttContainerDescriptor.name] },
48	  });
49	  if (dockerContainer.length > 0) {
50	    [container] = dockerContainer;
51	    await this.gladys.system.stopContainer(container.id);
52	    await this.gladys.system.removeContainer(container.id);
53	  }
54	  this.zigbee2mqttRunning = false;
55	  this.zigbee2mqttConnected = false;
56	  this.coordinatorFirmware = null;
57	  this.z2mContainerError = null;
58	  this.emitStatusEvent();
59	}
60	
61	module.exports = {
62	  disconnect,
63	};
